package de.lazytv.pro.catalog;
import org.json.*;import java.util.*;import android.content.Context;import de.lazytv.pro.playlist.Playlist;
public class XtreamCatalogSource {private final Context context;public XtreamCatalogSource(){this.context=null;}public XtreamCatalogSource(Context c){this.context=c==null?null:c.getApplicationContext();}public Catalog load(Playlist p)throws CatalogException {
 try{return loadApi(p);}catch(ProviderHttpException error){if(error.status==401||error.status==403)throw error;return loadM3u(p,null);}
}
public Catalog loadType(Playlist p,CatalogType type)throws CatalogException {
 try{return loadApiType(p,type);}catch(ProviderHttpException error){if(error.status!=404&&error.status!=405)throw error;return loadM3u(p,type);}
}
private Catalog loadM3u(Playlist p,CatalogType wanted)throws CatalogException {
 Catalog full=new M3uCatalogSource().loadExactRemote(XtreamUrlBuilder.m3u(p));
 if(wanted==null)return full;Catalog selected=new Catalog();selected.categories.addAll(full.categories(wanted));selected.items.addAll(full.items(wanted,null));
 if(selected.isEmpty())throw new CatalogException("Playlist M3U nuk përmban këtë rubrikë");return selected;
}
private Catalog loadApiType(Playlist p,CatalogType wanted)throws CatalogException{String base=base(p),q=auth(p);JSONObject login=obj(HttpClient.get(XtreamUrlBuilder.api(p,null),null));JSONObject ui=login.optJSONObject("user_info");if(ui==null||!"1".equals(ui.optString("auth")))throw new CatalogException("Xtream credentials janë të gabuara ose llogaria nuk është aktive");Catalog c=new Catalog();if(wanted==CatalogType.LIVE)loadType(c,base,p,"get_live_categories","get_live_streams",CatalogType.LIVE);else if(wanted==CatalogType.MOVIES)loadType(c,base,p,"get_vod_categories","get_vod_streams",CatalogType.MOVIES);else if(wanted==CatalogType.SERIES)loadType(c,base,p,"get_series_categories","get_series",CatalogType.SERIES);if(c.isEmpty())throw new CatalogException("Xtream u lidh, por kjo rubrikë është bosh");return c;}private Catalog loadApi(Playlist p)throws CatalogException{String base=base(p),q=auth(p);JSONObject login=obj(HttpClient.get(XtreamUrlBuilder.api(p,null),null));JSONObject ui=login.optJSONObject("user_info");if(ui==null||!"1".equals(ui.optString("auth")))throw new CatalogException("Xtream credentials janë të gabuara ose llogaria nuk është aktive");Catalog c=new Catalog();loadType(c,base,p,"get_live_categories","get_live_streams",CatalogType.LIVE);loadOptional(c,base,p,"get_vod_categories","get_vod_streams",CatalogType.MOVIES);loadOptional(c,base,p,"get_series_categories","get_series",CatalogType.SERIES);if(c.isEmpty())throw new CatalogException("Xtream u lidh, por katalogu është bosh");return c;}public SeriesDetails loadSeries(Playlist p,String seriesId)throws CatalogException{JSONObject root=obj(HttpClient.get(XtreamUrlBuilder.api(p,"get_series_info","series_id",seriesId),null));SeriesDetails d=new SeriesDetails();JSONObject info=root.optJSONObject("info");if(info!=null)d.metadata.putAll(ProviderMetadata.read(info));String defaultCover=info==null?"":info.optString("cover");JSONArray ss=root.optJSONArray("seasons");if(ss!=null)for(int i=0;i<ss.length();i++){JSONObject s=ss.optJSONObject(i);if(s==null)continue;int n=s.optInt("season_number",s.optInt("season",i+1));d.seasons.add(new Season(String.valueOf(n),s.optString("name","Season "+n),seriesId,n,s.optString("cover",defaultCover)));}JSONObject eps=root.optJSONObject("episodes");if(eps!=null){Iterator<String> it=eps.keys();while(it.hasNext()){String key=it.next();JSONArray a=eps.optJSONArray(key);if(a==null)continue;int sn=intval(key,0);List<Episode> list=d.episodes.computeIfAbsent(sn,k->new ArrayList<>());for(int i=0;i<a.length();i++){JSONObject e=a.optJSONObject(i);if(e==null)continue;String id=e.optString("id",e.optString("stream_id"));JSONObject ei=e.optJSONObject("info");String ext=e.optString("container_extension",ei==null?"mp4":ei.optString("container_extension","mp4"));if(ext==null||ext.trim().isEmpty()||"null".equalsIgnoreCase(ext))ext="mp4";int en=e.optInt("episode_num",i+1);int season=e.optInt("season",sn);String title=e.optString("title",e.optString("name","Episode "+en));String image=ei==null?defaultCover:ei.optString("movie_image",ei.optString("cover_big",defaultCover));String duration=ei==null?"":ei.optString("duration");Map<String,String> meta=new LinkedHashMap<>(ProviderMetadata.read(ei));if(ei!=null)put(meta,"releasedate",ei.optString("releasedate"));String url=XtreamUrlBuilder.stream(base(p),p,"series",id,ext);list.add(new Episode(id,title,seriesId,"",image,url,ext,duration,season,en,meta));}}}if(d.seasons.isEmpty())for(Integer n:d.episodes.keySet())d.seasons.add(new Season(String.valueOf(n),"Season "+n,seriesId,n,defaultCover));if(d.isEmpty())throw new CatalogException("Seriali nuk ka sezone ose episode");return d;}private void loadType(Catalog c,String b,Playlist p,String ca,String ia,CatalogType t)throws CatalogException{String q="&"+auth(p);JSONArray cats=arr(HttpClient.get(XtreamUrlBuilder.api(p,ca),null));LinkedHashMap<String,String> known=new LinkedHashMap<>();for(int i=0;i<cats.length();i++){JSONObject o=cats.optJSONObject(i);if(o!=null){String cid=o.optString("category_id").trim();String cn=o.optString("category_name","Të tjera").trim();if(!cid.isEmpty()){known.put(cid,cn);c.categories.add(new Category(cid,cn,t));}}}JSONArray a=arr(HttpClient.get(XtreamUrlBuilder.api(p,ia),null));LinkedHashMap<String,Integer> missing=new LinkedHashMap<>();for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;String id=t==CatalogType.SERIES?o.optString("series_id"):o.optString("stream_id");String ext=o.optString("container_extension",t==CatalogType.LIVE?"ts":"mp4");if(t==CatalogType.LIVE&&(ext==null||ext.trim().isEmpty()||"null".equalsIgnoreCase(ext)))ext="ts";if(t==CatalogType.LIVE&&context!=null){String forced=context.getSharedPreferences("lazytv_player_settings",Context.MODE_PRIVATE).getString("live_stream_format","auto");if("ts".equals(forced))ext="ts";else if("m3u8".equals(forced))ext="m3u8";}String url=t==CatalogType.LIVE?XtreamUrlBuilder.stream(b,p,"live",id,ext):t==CatalogType.MOVIES?XtreamUrlBuilder.stream(b,p,"movie",id,ext):"";String cid=o.optString("category_id").trim();String providerCategory=known.get(cid);String providerCountry=o.optString("country",o.optString("country_code",o.optString("stream_country",""))).trim();if((providerCountry==null||providerCountry.isEmpty())&&providerCategory!=null){String ck=CountryResolver.key(providerCategory);if(!"OTHER".equals(ck))providerCountry=ck;}if(cid.isEmpty()||"0".equals(cid)||"null".equalsIgnoreCase(cid)){String inferred=o.optString("category_name",o.optString("group_title","")).trim();if(!inferred.isEmpty()){cid="inferred-"+Integer.toHexString((t.name()+"|"+inferred).hashCode());if(!known.containsKey(cid)){known.put(cid,inferred);c.categories.add(new Category(cid,inferred,t));}}else cid="uncategorized";}if(!known.containsKey(cid))missing.put(cid,missing.containsKey(cid)?missing.get(cid)+1:1);java.util.Map<String,String> meta=metadata(o);c.items.add(CatalogItems.create(id,o.optString("name","Stream"),cid,poster(o),url,o.optString("epg_channel_id"),t,meta));}for(Map.Entry<String,Integer>e:missing.entrySet()){String cid=e.getKey();String label="Kategori "+cid;if("uncategorized".equals(cid))label="Të pakategorizuara";c.categories.add(new Category(cid,label,t));} java.util.List<Category> fixed=new java.util.ArrayList<>();for(Category z:c.categories){if(z.type!=t){fixed.add(z);continue;}String country=z.country;if(country==null||country.isEmpty()){String ck=CountryResolver.key(z.name);country="OTHER".equals(ck)?"":ck;}fixed.add(new Category(z.id,z.name,z.type,country));}c.categories.clear();c.categories.addAll(fixed); }public Map<String,String> loadLiveEpg(Playlist p,String streamId)throws CatalogException{Map<String,String> out=new LinkedHashMap<>();if(streamId==null||streamId.trim().isEmpty())return out;String u=XtreamUrlBuilder.api(p,"get_short_epg","stream_id",streamId,"limit","2");JSONObject root=obj(HttpClient.get(u,null));JSONArray a=root.optJSONArray("epg_listings");if(a==null||a.length()==0)return out;for(int n=0;n<Math.min(2,a.length());n++){JSONObject e=a.optJSONObject(n);if(e==null)continue;String title=decodeEpg(e.optString("title"));String start=epgTime(e,"start","start_timestamp");String end=epgTime(e,"end","stop_timestamp");String label=((start.isEmpty()?"":start+(end.isEmpty()?"":" - "+end)+"  ")+title).trim();if(n==0)out.put("epg_now",label);else out.put("epg_next",label);String desc=decodeEpg(e.optString("description"));if(!desc.trim().isEmpty())out.put(n==0?"epg_now_description":"epg_next_description",desc.trim());}return out;}private String epgTime(JSONObject e,String textKey,String timestampKey){String ts=e.optString(timestampKey,"").trim();if(!ts.isEmpty()){try{long v=Long.parseLong(ts);if(v>999999999999L)v/=1000L;java.text.SimpleDateFormat f=new java.text.SimpleDateFormat("HH:mm",java.util.Locale.getDefault());return f.format(new java.util.Date(v*1000L));}catch(Exception ignored){}}String raw=e.optString(textKey,"").trim();if(raw.isEmpty())return"";try{java.text.SimpleDateFormat in=new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss",java.util.Locale.US);in.setLenient(false);java.util.Date d=in.parse(raw);if(d!=null)return new java.text.SimpleDateFormat("HH:mm",java.util.Locale.getDefault()).format(d);}catch(Exception ignored){}if(raw.matches("\\d{2}:\\d{2}(:\\d{2})?"))return raw.substring(0,5);return raw;}private String decodeEpg(String s){if(s==null)return"";try{byte[] b=android.util.Base64.decode(s,android.util.Base64.DEFAULT);String x=new String(b,java.nio.charset.StandardCharsets.UTF_8).trim();if(!x.isEmpty()&&x.chars().filter(ch->ch>=32||ch=='\n'||ch=='\r'||ch=='\t').count()>x.length()*0.8)return x;}catch(Exception ignored){}return s;}
private java.util.Map<String,String> metadata(JSONObject o){java.util.Map<String,String> m=new java.util.LinkedHashMap<>();put(m,"plot",first(o,"plot","description","overview"));put(m,"rating",first(o,"rating","rating_5based","imdb_rating"));put(m,"year",first(o,"year","releaseDate","releasedate","release_date"));put(m,"genre",first(o,"genre","genres"));put(m,"duration",first(o,"duration","duration_secs"));return m;}private String first(JSONObject o,String...keys){for(String k:keys){String v=o.optString(k,"").trim();if(!v.isEmpty()&&!"null".equalsIgnoreCase(v))return v;}return "";}
private String poster(JSONObject o){String[] keys={"stream_icon","cover","cover_big","movie_image","poster","image"};for(String k:keys){String v=o.optString(k,"").trim();if(!v.isEmpty()&&!"null".equalsIgnoreCase(v))return v;}JSONArray b=o.optJSONArray("backdrop_path");if(b!=null&&b.length()>0){String v=b.optString(0,"").trim();if(!v.isEmpty())return v;}return "";}
private void loadOptional(Catalog c,String base,Playlist p,String categories,String items,CatalogType type)throws CatalogException {
 Catalog optional=new Catalog();
 try { loadType(optional,base,p,categories,items,type);c.categories.addAll(optional.categories);c.items.addAll(optional.items); }
 catch(ProviderHttpException error){if(error.status!=404&&error.status!=405)throw error;}
}
private String base(Playlist p)throws CatalogException{return XtreamUrlBuilder.base(p.getUrl());}private String auth(Playlist p){return "username="+HttpClient.enc(p.getUsername())+"&password="+HttpClient.enc(p.getPassword());}private JSONObject obj(String s)throws CatalogException{try{return new JSONObject(s);}catch(Exception e){throw new CatalogException("Përgjigje Xtream e pavlefshme",e);}}private JSONArray arr(String s)throws CatalogException{try{return new JSONArray(s);}catch(Exception e){throw new CatalogException("Përgjigje Xtream e pavlefshme",e);}}private int intval(String s,int d){try{return Integer.parseInt(s);}catch(Exception e){return d;}}private static void put(Map<String,String>m,String k,String v){if(v!=null&&!v.isEmpty())m.put(k,v);}}
